  "mercedes-eqe-300-electrico-precio-ficha-tecnica": { lanzamiento: 2022, hitos: [{ anio: 2021, tipo: "lanzamiento", cambio: "Estreno mundial en el IAA de Múnich en septiembre: segunda familia sobre la arquitectura EVA2 tras el EQS, con silueta de un solo arco, producción anunciada en Bremen y Pekín y venta prevista para mediados de 2022.", foto: null }, { anio: 2022, tipo: "lanzamiento", cambio: "Las ventas españolas arrancaron en abril con el EQE 350 de 292 CV y tracción trasera; la gama berlina nacía como alternativa eléctrica situada inmediatamente por debajo del EQS dentro de la oferta Mercedes-EQ.", foto: null }, { anio: 2022, tipo: "restyling", cambio: "En verano llegó este EQE 300 de acceso: motor trasero de 245 CV, 550 Nm y batería útil de 89 kWh, manteniendo el enfoque viajero del modelo con una tarifa inferior a la del 350 inicial.", foto: null }, { anio: 2024, tipo: "restyling", cambio: "La gama 2024 incorporó bomba de calor de serie y un sistema de frenado revisado buscando mejor tacto de pedal, además de desconexión del motor delantero en las variantes 4MATIC para arañar autonomía real.", foto: null }, { anio: 2025, tipo: "restyling", cambio: "En abril de 2025 Mercedes elevó este 300 hasta 265 CV y rehomologó su autonomía en 663 km, evolución posterior a la configuración de 245 CV recogida en esta ficha concreta.", foto: null }] },
