  "bmw-i4-edrive40-electrico-precio-ficha-tecnica": { lanzamiento: 2021, hitos: [{ anio: 2020, tipo: "lanzamiento", cambio: "BMW desveló el Concept i4, anticipo casi definitivo del Gran Coupé eléctrico de producción, con pantalla curva orientada al conductor y una parrilla cerrada que alojaba sensores en lugar de refrigerar un motor térmico.", foto: null }, { anio: 2021, tipo: "lanzamiento", cambio: "El lanzamiento comercial llegó en noviembre: el eDrive40 debutó con motor trasero de 340 CV, propulsión trasera clásica de la casa y hasta 590 km WLTP, acompañado del M50, primer eléctrico firmado por BMW M.", foto: null }, { anio: 2024, tipo: "restyling", cambio: "La actualización de mitad de ciclo, con producción en Múnich desde julio, estrenó faros y pilotos revisados, sumó el xDrive40 de tracción total y mantuvo al eDrive40 como opción trasera pensada para devorar kilómetros.", foto: null }, { anio: 2025, tipo: "restyling", cambio: "BMW introdujo semiconductores de carburo de silicio en la electrónica de potencia del eDrive40, recortando el consumo y elevando la autonomía homologada hasta los 613 km que figuran en esta ficha actual.", foto: null }] },
  "audi-q4-e-tron-45-electrico-precio-ficha-tecnica": { lanzamiento: 2021, hitos: [{ anio: 2021, tipo: "lanzamiento", cambio: "Presentado en abril de 2021 y fabricado en Zwickau, fue el primer SUV eléctrico de Audi construido en Alemania: estrenó la plataforma MEB en la marca, con versiones 35, 40 y 50 quattro y llegada a Europa en verano.", foto: null }, { anio: 2023, tipo: "restyling", cambio: "En septiembre de 2023 Audi renovó el tren motriz para 2024: el nuevo motor trasero APP550 convirtió el antiguo 40 en este 45 de 286 CV y 545 Nm, con batería de 77 kWh.", foto: null }, { anio: 2025, tipo: "restyling", cambio: "En 2025 Euro NCAP reevaluó el modelo con el protocolo vigente y mantuvo las cinco estrellas, probando precisamente un Q4 e-tron 45 con volante a la izquierda.", foto: null }] },
