  "volkswagen-touareg-r-ehybrid-2026-precio-ficha-tecnica": { lanzamiento: 2018, hitos: [{ anio: 2018, tipo: "lanzamiento", cambio: null, foto: null }, { anio: 2023, tipo: "restyling", cambio: "restyling/facelift de mitad de ciclo", foto: null }, { anio: 2026, tipo: "fin", cambio: null, foto: null }] },
  "audi-a5-avant-e-hybrid-2026-precio-ficha-tecnica": { lanzamiento: 2024, hitos: [{ anio: 2024, tipo: "lanzamiento", cambio: "Audi presentó la nueva familia A5 el 16 de julio de 2024: el relevo del A4 estrenó la plataforma PPC, con carrocerías Sedan y Avant fabricadas en Neckarsulm y una nomenclatura que reserva los números impares a la combustión.", foto: null }, { anio: 2025, tipo: "lanzamiento", cambio: "El 25 de marzo de 2025 Audi España anunció las versiones e-hybrid quattro de 299 y 367 CV: estrenaban nombre comercial, batería de 25,9 kWh y hasta 110 km de alcance eléctrico homologado para el conjunto de la familia.", foto: null }] },
  "audi-a6-avant-e-hybrid-2026-precio-ficha-tecnica": { lanzamiento: 2025, hitos: [{ anio: 1994, tipo: "lanzamiento", cambio: "El Audi 100 pasó a llamarse A6 al adoptar la marca su nueva nomenclatura alfanumérica, manteniendo la carrocería familiar Avant que ya definía a la saga desde la etapa del 100.", foto: null }, { anio: 2018, tipo: "restyling", cambio: "La generación C8 se presentó en el Salón de Ginebra y semanas después llegó su carrocería Avant; es el familiar que este C9 sustituye, ya con hibridación ligera en parte de la gama.", foto: null }, { anio: 2025, tipo: "lanzamiento", cambio: "Audi presentó el nuevo A6 Avant sobre la Plataforma Premium de Combustión, con un coeficiente aerodinámico de 0,25 y la carrocería familiar ejerciendo de versión de estreno de la novena generación.", foto: null }, { anio: 2025, tipo: "lanzamiento", cambio: "En mayo de 2025 se sumó este e-hybrid quattro: motor 2.0 TFSI de 252 CV, batería de 25,9 kWh —un 45 % mayor— y pedidos abiertos en España desde el 8 de mayo.", foto: null }] },
  "audi-q5-sportback-e-hybrid-2026-precio-ficha-tecnica": { lanzamiento: 2024, hitos: [{ anio: 2024, tipo: "lanzamiento", cambio: "Audi presentó en noviembre de 2024 la segunda generación del Q5 Sportback, primer SUV de la marca sobre la plataforma PPC, con silueta coupé, interior panorámico digital y motores de combustión con tecnología MHEV plus.", foto: null }, { anio: 2025, tipo: "lanzamiento", cambio: "En junio de 2025 llegó esta versión e-hybrid concreta: 2.0 TFSI más motor eléctrico, 299 CV conjuntos, batería de 25,9 kWh, carga alterna de 11 kW y tracción quattro con cambio S tronic.", foto: null }] },
  "audi-q3-sportback-tdi-2026-precio-ficha-tecnica": { lanzamiento: 2025, hitos: [{ anio: 2025, tipo: "lanzamiento", cambio: null, foto: null }] },
  "audi-q3-e-hybrid-2026-precio-ficha-tecnica": { lanzamiento: 2025, hitos: [{ anio: 2011, tipo: "lanzamiento", cambio: "El Q3 original se desveló en el Salón de Shanghái de 2011 como SUV de acceso de Audi, por debajo del Q5, y abrió a la marca un segmento compacto que hasta entonces no cubría.", foto: null }, { anio: 2018, tipo: "restyling", cambio: "La segunda generación llegó en 2018 con más tamaño y un habitáculo ya digital; en 2019 sumó la carrocería Sportback de silueta coupé, que se convirtió en una parte importante de las ventas del modelo.", foto: null }, { anio: 2025, tipo: "lanzamiento", cambio: "La tercera generación se presentó en junio de 2025 y su variante e-hybrid estrenó batería de 25,7 kWh con carga en continua a 50 kW, casi el doble de capacidad que la batería del enchufable anterior.", foto: null }] },
  "audi-sq8-2026-precio-ficha-tecnica": { lanzamiento: 2019, hitos: [{ anio: 2019, tipo: "lanzamiento", cambio: "Audi presentó el SQ8 TDI en julio de 2019: V8 diésel biturbo de 4,0 litros con 435 CV y 900 Nm, compresor eléctrico alimentado por la red de 48 V y tracción quattro; llegó a Europa a finales de verano.", foto: null }, { anio: 2020, tipo: "restyling", cambio: "En julio de 2020 el SQ8 abandonó el diésel y adoptó el 4.0 TFSI de gasolina: V8 biturbo de 507 CV y 770 Nm con desactivación de cilindros, 0 a 100 km/h en 4,1 segundos y lanzamiento europeo en otoño.", foto: null }, { anio: 2023, tipo: "restyling", cambio: "La actualización presentada en septiembre de 2023 renovó la parrilla Singleframe, estrenó faros HD Matrix LED con luz láser opcional y pilotos traseros OLED digitales; el SQ8 mantuvo el V8 de 507 CV y 770 Nm sin cambios de potencia.", foto: null }] },
  "audi-a3-allstreet-tfsi-2026-precio-ficha-tecnica": { lanzamiento: 2020, hitos: [{ anio: 2020, tipo: "lanzamiento", cambio: null, foto: null }, { anio: 2024, tipo: "restyling", cambio: "restyling/facelift de mitad de ciclo", foto: null }] },
  "audi-q4-sportback-e-tron-45-2026-precio-ficha-tecnica": { lanzamiento: 2021, hitos: [{ anio: 2021, tipo: "lanzamiento", cambio: "Audi lo desveló en abril junto al Q4 e-tron de techo recto: misma plataforma MEB y producción en Zwickau, pero con silueta coupé, luneta partida por un alerón y un Cx de 0,26 pensado para arañar autonomía en carretera.", foto: null }, { anio: 2024, tipo: "restyling", cambio: "La actualización de modelo 2024 sustituyó al Sportback 40 de 204 CV por este 45: estrenó motor síncrono trasero de 286 CV y 545 Nm, mantuvo la batería de 82 kWh y añadió preacondicionamiento térmico antes de cargar.", foto: null }] },
  "audi-q6-sportback-e-tron-2026-precio-ficha-tecnica": { lanzamiento: 2024, hitos: [{ anio: 2024, tipo: "lanzamiento", cambio: "El Q6 e-tron SUV se presentó el 18 de marzo de 2024 como primer Audi de producción sobre la plataforma PPE de 800 voltios, desarrollada junto a Porsche para sus eléctricos premium.", foto: null }, { anio: 2024, tipo: "restyling", cambio: "El 14 de octubre de 2024, en el Salón de París, llegó esta carrocería Sportback: techo descendente, Cx 0,26 y 37 milímetros menos de altura que el SUV, manteniendo plataforma y baterías.", foto: null }, { anio: 2024, tipo: "restyling", cambio: "Audi España abrió pedidos el 21 de noviembre de 2024 con un sobreprecio Sportback de 2.450 euros frente al SUV; esta versión performance de tracción trasera encabezaba la oferta por autonomía homologada.", foto: null }] },
