  "mercedes-cla-250-plus-eq-2026-precio-ficha-tecnica": { lanzamiento: 2025, hitos: [{ anio: 2025, tipo: "lanzamiento", cambio: null, foto: null }] },
  "mercedes-glc-400-eq-2026-precio-ficha-tecnica": { lanzamiento: 2025, hitos: [{ anio: 2015, tipo: "lanzamiento", cambio: "El GLC original debutó en 2015 reemplazando al GLK de formas rectas: adoptó un diseño mucho más redondeado, se posicionó como el SUV ligado a la Clase C y sentó las bases del superventas actual.", foto: null }, { anio: 2019, tipo: "restyling", cambio: "Mercedes lanzó el EQC, su primer eléctrico de la familia EQ y antecesor directo en planteamiento: un SUV derivado del GLC térmico, con dos motores y producción iniciada en Bremen aquel mismo año.", foto: null }, { anio: 2022, tipo: "restyling", cambio: "La segunda generación del GLC de combustión llegó en 2022 con la gama ya electrificada mediante híbridos e híbridos enchufables, manteniendo al modelo como el Mercedes más vendido antes de dar el salto eléctrico puro.", foto: null }, { anio: 2025, tipo: "lanzamiento", cambio: "El 7 de septiembre de 2025, en la víspera del IAA de Múnich, Mercedes presentó este GLC eléctrico sobre la plataforma específica MB.EA: arquitectura de 800 voltios, sistema MB.OS y versión inicial 400 4MATIC.", foto: null }] },
