  "mercedes-gle-450-e-2026-precio-ficha-tecnica": { lanzamiento: 2018, hitos: [{ anio: 2018, tipo: "lanzamiento", cambio: null, foto: null }, { anio: 2023, tipo: "restyling", cambio: "restyling/facelift de mitad de ciclo", foto: null }] },
  "mercedes-g-580-eq-2026-precio-ficha-tecnica": { lanzamiento: 2024, hitos: [{ anio: 1979, tipo: "lanzamiento", cambio: "La Clase G nació en primavera de 1979 fabricada en Graz junto a Steyr-Daimler-Puch: Geländewagen de largueros, carrocerías descapotable y familiar, y motores entre 72 y 150 CV pensados primero para trabajo y uso militar.", foto: null }, { anio: 2018, tipo: "lanzamiento", cambio: "En enero de 2018 Detroit acogió la generación actual: conservó largueros, tres bloqueos y silueta cúbica, creció en anchura y estrenó suspensión delantera independiente y un habitáculo ya de berlina de lujo.", foto: null }, { anio: 2021, tipo: "restyling", cambio: "El Concept EQG desvelado en el IAA de Múnich de 2021 anticipó casi todo: cuatro motores, reductora de dos relaciones, panel frontal cerrado e iluminado y una caja trasera ocupando el sitio de la rueda de repuesto.", foto: null }, { anio: 2024, tipo: "lanzamiento", cambio: "El 24 de abril de 2024 debutó el G 580 con tecnología EQ, primer Clase G eléctrico de serie: batería de 116 kWh integrada en el chasis, 432 kW conjuntos y funciones G-TURN y G-STEERING para girar entre obstáculos.", foto: null }] },
  "mercedes-eqs-suv-580-2026-precio-ficha-tecnica": { lanzamiento: 2022, hitos: [{ anio: 2022, tipo: "lanzamiento", cambio: "Estreno mundial el 19 de abril de 2022 como tercer modelo sobre la arquitectura eléctrica dedicada de Mercedes-Benz, tras las berlinas EQS y EQE, y primer SUV de lujo totalmente eléctrico de la marca, fabricado en Tuscaloosa (Alabama).", foto: null }, { anio: 2022, tipo: "restyling", cambio: "La gama inicial situó al 580 4MATIC en lo más alto: dos motores, 544 CV y 858 Nm, batería de 107,8 kWh y tercera fila opcional de dos asientos para llegar hasta siete plazas.", foto: null }, { anio: 2023, tipo: "restyling", cambio: "En abril de 2023, en el Salón de Shanghái, debutó el Mercedes-Maybach EQS 680 SUV, primer modelo de serie totalmente eléctrico de Maybach, derivado directamente de esta misma plataforma.", foto: null }] },
  "mercedes-amg-gt-43-2026-precio-ficha-tecnica": { lanzamiento: 2023, hitos: [{ anio: 2023, tipo: "lanzamiento", cambio: null, foto: null }] },
  "mercedes-eqv-300-largo-2026-precio-ficha-tecnica": { lanzamiento: 2020, hitos: [{ anio: 2014, tipo: "lanzamiento", cambio: "La Clase V de la generación W447 llegó en 2014 como versión de pasajeros derivada de la Vito y fabricada en Vitoria: esa base de furgoneta premium es la que años después recibiría la electrificación completa.", foto: null }, { anio: 2019, tipo: "restyling", cambio: "Mercedes-Benz Vans enseñó el Concept EQV en el Salón de Ginebra de marzo de 2019 y presentó la versión de serie en el IAA de Fráncfort, anunciada como primer monovolumen premium totalmente eléctrico.", foto: null }, { anio: 2020, tipo: "lanzamiento", cambio: "La producción en serie arrancó en la planta de Vitoria y las primeras unidades llegaron a los concesionarios españoles a mediados de septiembre, con paquete de mantenimiento integrado durante cuatro años en el lanzamiento nacional.", foto: null }, { anio: 2023, tipo: "restyling", cambio: "En julio de 2023 se desveló la renovación prevista para 2024: frontal rediseñado, salpicadero con dos pantallas de 12,3 pulgadas y MBUX actualizado, además de más asistentes de serie. Esta EQV 300 Largo hereda directamente aquella actualización.", foto: null }] },
