  "porsche-taycan-4s-2026-precio-ficha-tecnica": { lanzamiento: 2019, hitos: [{ anio: 2019, tipo: "lanzamiento", cambio: null, foto: null }, { anio: 2024, tipo: "restyling", cambio: "restyling/facelift de mitad de ciclo", foto: null }] },
  "porsche-taycan-turbo-2026-precio-ficha-tecnica": { lanzamiento: 2019, hitos: [{ anio: 2015, tipo: "lanzamiento", cambio: "Prototipo Mission E presentado en el Salón de Fráncfort de 2015: anticipó arquitectura de 800 voltios, dos motores eléctricos y más de 500 kilómetros de autonomía objetivo antes de existir el nombre Taycan.", foto: null }, { anio: 2019, tipo: "lanzamiento", cambio: "Estreno mundial simultáneo en tres continentes el 4 de septiembre de 2019, con Turbo y Turbo S abriendo la gama: primer deportivo totalmente eléctrico de Porsche, fabricado en Zuffenhausen.", foto: null }, { anio: 2024, tipo: "restyling", cambio: "Extensa actualización de febrero de 2024, conocida como J1 II: la batería Plus crece hasta 105 kWh, la carga sube a 320 kW y este Turbo alcanza 884 CV, con suspensión neumática adaptativa de serie.", foto: null }] },
