  "porsche-panamera-turbo-e-hybrid-2026-precio-ficha-tecnica": { lanzamiento: 2024, hitos: [{ anio: 2024, tipo: "lanzamiento", cambio: null, foto: null }] },
  "porsche-macan-4-electric-2026-precio-ficha-tecnica": { lanzamiento: 2024, hitos: [{ anio: 2014, tipo: "lanzamiento", cambio: "Porsche estrenó el Macan en 2014 como hermano pequeño del Cayenne: SUV compacto fabricado en Leipzig, con motores de gasolina y diésel, que acabó convirtiéndose en uno de los pilares comerciales de la marca.", foto: null }, { anio: 2018, tipo: "restyling", cambio: "La primera generación se actualizó en 2018 con una banda luminosa que une los pilotos traseros, pantalla táctil de 10,9 pulgadas para el PCM y ajustes de chasis orientados a mantener su tacto deportivo.", foto: null }, { anio: 2024, tipo: "lanzamiento", cambio: "La segunda generación se desveló en Singapur el 25 de enero de 2024: dijo adiós a la combustión y estrenó una arquitectura de 800 voltios sobre la plataforma PPE, con el Macan 4 y el Turbo como versiones de lanzamiento.", foto: null }, { anio: 2024, tipo: "restyling", cambio: "Esta variante 4 combina dos motores síncronos, uno por eje, para firmar 408 CV con Launch Control, 650 Nm y tracción total, alimentados por una batería bruta de 100 kWh alojada en el suelo.", foto: null }] },
  "porsche-macan-turbo-electric-2026-precio-ficha-tecnica": { lanzamiento: 2024, hitos: [{ anio: 2014, tipo: "lanzamiento", cambio: "El Macan original llegó en la primavera de 2014 como SUV situado bajo el Cayenne, fabricado en Leipzig y con versiones S y Turbo de gasolina; su nombre procede de la palabra indonesia que significa tigre.", foto: null }, { anio: 2018, tipo: "restyling", cambio: "La actualización de la primera generación se desveló en Shanghái en 2018 y llegó después a Europa: banda luminosa LED trasera continua, pantalla del sistema PCM ampliada hasta 10,9 pulgadas y un chasis puesto al día.", foto: null }, { anio: 2024, tipo: "lanzamiento", cambio: "El 25 de enero de 2024, Singapur acogió el estreno mundial de la segunda generación, ya únicamente eléctrica, construida sobre la plataforma PPE de 800 voltios que comparte con el Audi Q6 e-tron.", foto: null }, { anio: 2024, tipo: "restyling", cambio: "El Turbo ocupó desde ese mismo debut la cúspide eléctrica del modelo: 639 CV con Launch Control, 1.130 Nm de par, batería de 100 kWh y una aceleración hasta 100 km/h cifrada en 3,3 segundos.", foto: null }] },
