  "cupra-tavascan-endurance-286-2026-precio-ficha-tecnica": { lanzamiento: 2023, hitos: [{ anio: 2019, tipo: "lanzamiento", cambio: "CUPRA desveló en el Salón de Fráncfort el Tavascan Concept, un prototipo de SUV coupé eléctrico sobre plataforma MEB que anticipó la firma lumínica de tres triángulos y el logotipo iluminado del modelo definitivo.", foto: null }, { anio: 2023, tipo: "lanzamiento", cambio: "La versión de producción se presentó en Berlín el 21 de abril: primer SUV coupé totalmente eléctrico de CUPRA, segundo eléctrico tras el Born, diseñado en Barcelona y fabricado en Anhui, China.", foto: null }, { anio: 2024, tipo: "restyling", cambio: "Inicio de la comercialización en Europa y cinco estrellas Euro NCAP en noviembre, con 89 % en ocupante adulto y 86 % en ocupante infantil; la gama incluye el Endurance trasero de 286 CV.", foto: null }] },
  "cupra-born-204-2026-precio-ficha-tecnica": { lanzamiento: 2021, hitos: [{ anio: 2021, tipo: "lanzamiento", cambio: "CUPRA lo presentó en mayo de 2021 como su primer coche cien por cien eléctrico: compacto sobre la plataforma MEB, diseñado en Martorell, producido en Zwickau y lanzado con esta potencia de 204 CV y tracción trasera.", foto: null }, { anio: 2026, tipo: "restyling", cambio: "En la configuración de esta ficha, el motor trasero rinde 204 CV con batería de 59 kWh, 428 km WLTP y carga rápida de 125 kW, con un precio de partida de 36.600 euros en España.", foto: null }] },
  "cupra-tavascan-190-2026-precio-ficha-tecnica": { lanzamiento: 2023, hitos: [{ anio: 2023, tipo: "lanzamiento", cambio: null, foto: null }] },
  "porsche-macan-electric-2026-precio-ficha-tecnica": { lanzamiento: 2024, hitos: [{ anio: 2024, tipo: "lanzamiento", cambio: "La segunda generación del Macan se presentó el 25 de enero de 2024 en Singapur ya como SUV exclusivamente eléctrico, estrenando la plataforma PPE de 800 voltios con las versiones Macan 4 y Macan Turbo.", foto: null }, { anio: 2024, tipo: "restyling", cambio: "En julio de 2024 llegó esta versión de acceso: un único motor en el eje trasero, 360 CV con Launch Control, 110 kg menos que el Macan 4 y 641 km WLTP, la mayor autonomía de la gama eléctrica.", foto: null }, { anio: 2024, tipo: "restyling", cambio: "En diciembre de 2024 el Macan eléctrico obtuvo las cinco estrellas de Euro NCAP, con un 90 % en protección de adultos y de ocupantes infantiles y un 83 % en usuarios vulnerables de la vía.", foto: null }] },
  "porsche-macan-4s-electric-2026-precio-ficha-tecnica": { lanzamiento: 2024, hitos: [{ anio: 2024, tipo: "lanzamiento", cambio: null, foto: null }] },
  "porsche-taycan-turbo-s-2026-precio-ficha-tecnica": { lanzamiento: 2019, hitos: [{ anio: 2019, tipo: "lanzamiento", cambio: null, foto: null }, { anio: 2024, tipo: "restyling", cambio: "restyling/facelift", foto: null }] },
  "porsche-cayenne-s-e-hybrid-2026-precio-ficha-tecnica": { lanzamiento: 2002, hitos: [{ anio: 2002, tipo: "lanzamiento", cambio: "Porsche estrenó su primer SUV y su primer modelo de producción con cuatro puertas, recuperando además el motor V8 que había abandonado al cesar el 928 en 1995.", foto: null }, { anio: 2010, tipo: "restyling", cambio: "La segunda generación se desveló en el Salón de Ginebra, compartiendo base con Touareg y Q7, aligerando el conjunto e incorporando por primera vez una variante híbrida a la familia.", foto: null }, { anio: 2014, tipo: "restyling", cambio: "El restyling de aquella generación trajo el S E-Hybrid enchufable, presentado en París como primer híbrido recargable dentro del segmento SUV premium según la propia trayectoria del modelo.", foto: null }, { anio: 2017, tipo: "restyling", cambio: "Stuttgart acogió en agosto la presentación de la tercera generación, identificada como 9YA, con chasis profundamente renovado y una digitalización interior que rompía con el salpicadero anterior.", foto: null }, { anio: 2023, tipo: "restyling", cambio: "Tras actualizarse la gama esa primavera, septiembre incorporó este S E-Hybrid entre E-Hybrid y Turbo E-Hybrid: batería de 25,9 kWh, cargador de 11 kW y neumática de serie.", foto: null }] },
  "porsche-panamera-gts-2026-precio-ficha-tecnica": { lanzamiento: 2009, hitos: [{ anio: 2009, tipo: "lanzamiento", cambio: "Debutó en abril de 2009 en el Salón de Shanghái como primera berlina de cuatro puertas de Porsche, con portón trasero, cuatro plazas y motores V8, recuperando el espíritu del prototipo 989.", foto: null }, { anio: 2012, tipo: "restyling", cambio: "La primera versión GTS llegó en 2012 con V8 atmosférico de 4,8 litros y 430 CV, chasis rebajado diez milímetros, frenos del Turbo y escape deportivo de serie.", foto: null }, { anio: 2016, tipo: "restyling", cambio: "La segunda generación, presentada en 2016, estrenó diseño más afilado, motores turboalimentados y la carrocería familiar Sport Turismo, manteniendo el formato de berlina deportiva con portón.", foto: null }, { anio: 2023, tipo: "restyling", cambio: "Presentada en noviembre de 2023 en Shanghái, la tercera generación renovó el habitáculo con Porsche Driver Experience, amplió la oferta híbrida enchufable y mantuvo versiones gasolina puras.", foto: null }, { anio: 2024, tipo: "restyling", cambio: "En julio de 2024 llegó este GTS de tercera generación junto al Turbo S E-Hybrid: V8 biturbo sin electrificación, veinte caballos más que su antecesor y puesta a punto específica.", foto: null }] },
  "porsche-911-carrera-cabriolet-2026-precio-ficha-tecnica": { lanzamiento: 2018, hitos: [{ anio: 2018, tipo: "lanzamiento", cambio: null, foto: null }, { anio: 2024, tipo: "restyling", cambio: "restyling/facelift (992.2)", foto: null }] },
  "porsche-cayenne-gts-2026-precio-ficha-tecnica": { lanzamiento: 2017, hitos: [{ anio: 2002, tipo: "lanzamiento", cambio: "Presentación mundial en París del primer Cayenne: Porsche entraba en los SUV con versiones S y Turbo, un movimiento polémico que acabó financiando a los deportivos de la casa.", foto: null }, { anio: 2007, tipo: "lanzamiento", cambio: "Debuta en Fráncfort el primer Cayenne GTS: V8 atmosférico de 405 CV, chasis específico para esta versión y la fórmula Gran Turismo Sport aplicada por primera vez a un modelo moderno.", foto: null }, { anio: 2017, tipo: "lanzamiento", cambio: "Tercera generación E3: nueva plataforma, motores sobrealimentados y hasta 65 kg menos que su antecesora pese a crecer, con un habitáculo mucho más digital que rompía con el salpicadero anterior.", foto: null }, { anio: 2020, tipo: "restyling", cambio: "El GTS de la generación E3 recupera un ocho cilindros biturbo de 4,0 litros y 460 CV tras la etapa del V6, y estrena además una carrocería Coupé inédita en esta versión.", foto: null }, { anio: 2023, tipo: "restyling", cambio: "Renovación profunda del Cayenne E3: frontal rediseñado, interior Porsche Driver Experience con cuadro curvado y más potencia en toda la gama, una actualización planteada casi como generación nueva.", foto: null }, { anio: 2024, tipo: "restyling", cambio: "Llegan los GTS del restyling: el ocho cilindros sube a 500 CV y 660 Nm, el chasis baja 10 mm y hereda piezas del Turbo GT, firmando 4,4 segundos hasta 100 km/h.", foto: null }] },
