  "hyundai-kona-electrico-135-2025-precio-ficha-tecnica": { lanzamiento: 2023, hitos: [{ anio: 2023, tipo: "lanzamiento", cambio: null, foto: "/media/historia-hyundai-kona-electrico-135-2025-precio-ficha-tecnica-2023.webp" }] },
  "alfa-romeo-tonale-phev-q4-270-precio-ficha-tecnica": { lanzamiento: 2022, hitos: [{ anio: 2022, tipo: "lanzamiento", cambio: "Presentado en febrero de 2022, el Tonale de producción estrenó la electrificación en Alfa Romeo y situó a la marca bajo el Stelvio, frente a Q3, X1 y GLA, con diseño derivado del prototipo de Ginebra 2019.", foto: null }, { anio: 2022, tipo: "restyling", cambio: "La variante enchufable Q4 coronó la gama ese mismo año combinando un 1.3 turbo delantero con motor eléctrico trasero, batería de 15,5 kWh y tracción integral sin conexión mecánica entre ejes.", foto: null }] },
  "bmw-i4-m60-xdrive-2025-precio-ficha-tecnica": { lanzamiento: 2021, hitos: [{ anio: 2021, tipo: "lanzamiento", cambio: "Presentación del primer i4: Gran Coupé eléctrico de cuatro puertas lanzado en noviembre de 2021, con el M50 de 544 CV como primer modelo M sin motor de combustión y el eDrive40 trasero de 340 CV.", foto: null }, { anio: 2024, tipo: "restyling", cambio: "Actualización de mitad de ciclo lanzada en julio de 2024: parrilla semicerrada rediseñada, faros LED con firma vertical, pilotos traseros Laserlight estilo M4 CSL e iDrive 8.5 con QuickSelect en la pantalla curva.", foto: null }, { anio: 2025, tipo: "restyling", cambio: "Nace esta versión: el M60 xDrive releva al M50 en 2025, sube a 601 CV con dos motores y tracción total, baja el 0-100 a 3,7 segundos y acompaña a los nuevos inversores de carburo de silicio.", foto: null }] },
  "bmw-i5-m60-xdrive-touring-2025": { lanzamiento: 2024, hitos: [{ anio: 2023, tipo: "lanzamiento", cambio: "BMW desvela el 24 de mayo la octava generación del Serie 5 en formato berlina, ya con versión eléctrica i5 y variante M60 xDrive de 601 CV sobre la arquitectura CLAR.", foto: null }, { anio: 2024, tipo: "lanzamiento", cambio: "El 7 de febrero se presenta la carrocería Touring de sexta generación, la primera con propulsión totalmente eléctrica, fabricada en Dingolfing junto a las versiones diésel e híbridas enchufables posteriores.", foto: null }, { anio: 2024, tipo: "restyling", cambio: "En mayo arranca la comercialización en Europa y Japón con el M60 xDrive Touring como tope eléctrico, batería útil de 81,2 kWh, 506 km WLTP y carga máxima de 205 kW.", foto: null }] },
  "byd-atto-2-dm-i-2026-precio-ficha-tecnica": { lanzamiento: 2024, hitos: [{ anio: 2024, tipo: "lanzamiento", cambio: "El 26 de marzo de 2024 BYD lanzó en China el Yuan Up, versión original de este modelo: un SUV del segmento B sobre la e-Platform 3.0 con batería Blade LFP, situado por debajo del Atto 3.", foto: null }, { anio: 2025, tipo: "restyling", cambio: "En enero de 2025 el modelo se presentó en Europa como Atto 2 eléctrico en el Salón de Bruselas, con batería Blade de 45,1 kWh y 312 km WLTP; su venta arrancó en febrero.", foto: null }, { anio: 2025, tipo: "restyling", cambio: "La variante DM-i debutó en octubre de 2025 en los Fleet Europe Days de Luxemburgo y se lanzó el 20 de noviembre: Active de 166 CV con 7,8 kWh o Boost de 212 CV con 18 kWh.", foto: null }] },
  "jaguar-i-pace-2025-precio-ficha-tecnica": { lanzamiento: 2018, hitos: [{ anio: 2016, tipo: "lanzamiento", cambio: "Jaguar presentó el I-PACE Concept en Los Ángeles en noviembre de 2016, un prototipo casi definitivo con cabina adelantada, dos motores eléctricos y la arquitectura específica que luego heredó el coche de serie.", foto: null }, { anio: 2018, tipo: "lanzamiento", cambio: "El modelo definitivo se desveló en Graz el 1 de marzo de 2018 y llegó a Europa en junio: 400 CV, batería de 90 kWh, tracción total y fabricación en Magna Steyr, Austria.", foto: null }, { anio: 2019, tipo: "restyling", cambio: "En 2019 arrasó en premios internacionales: World Car of the Year, World Green Car, World Car Design of the Year y Coche del Año en Europa, algo inédito hasta entonces para Jaguar.", foto: null }, { anio: 2024, tipo: "restyling", cambio: "La producción en Graz terminó en diciembre de 2024 sin sucesor directo con ese nombre, dentro del giro de Jaguar hacia una gama eléctrica nueva y de posicionamiento más exclusivo.", foto: null }] },
  "kia-pv5-2026-precio-ficha-tecnica": { lanzamiento: 2025, hitos: [{ anio: 2024, tipo: "lanzamiento", cambio: "Kia mostró el Concept PV5 en el CES 2024 de Las Vegas como anticipo de su estrategia Platform Beyond Vehicle, con carrocerías intercambiables sobre una base eléctrica modular pensada para pasajeros, reparto y transformaciones profesionales.", foto: null }, { anio: 2025, tipo: "lanzamiento", cambio: "El 27 de febrero de 2025, en el Kia EV Day de Tarragona, debutó el PV5 de producción sobre la plataforma E-GMP.S, en versiones Passenger, Cargo y Chasis Cabina, con ventas europeas previstas para la segunda mitad del año.", foto: null }] },
  "lancia-ypsilon-hf-2025-precio-ficha-tecnica": { lanzamiento: 2024, hitos: [{ anio: 1960, tipo: "lanzamiento", cambio: "Las siglas HF nacen vinculadas al club Lancia Hi-Fi de clientes fieles y después identifican a los Lancia de competición, del Fulvia al Stratos y al Delta de rallies.", foto: null }, { anio: 2024, tipo: "lanzamiento", cambio: "El 14 de febrero de 2024 Lancia presenta en Milán el nuevo Ypsilon, su primer modelo en más de una década y su primer eléctrico puro, estrenado como edición limitada Cassina de 1.906 unidades.", foto: null }, { anio: 2024, tipo: "restyling", cambio: "Ese mismo año la marca desvela el logotipo HF actualizado, con colores del Fulvia Coupé de 1966, y anuncia un Ypsilon HF de calle para 2025 junto al regreso a los rallies con el Rally4 HF.", foto: null }, { anio: 2025, tipo: "restyling", cambio: "En junio de 2025, en Balocco, debuta el Ypsilon HF de producción: 280 CV, 5,6 segundos hasta 100 km/h, diferencial Torsen y producción en Figueruelas, con llegada a carretera tras el verano.", foto: null }] },
  "lynk-co-08-emp-2026-precio-ficha-tecnica": { lanzamiento: 2023, hitos: [{ anio: 2023, tipo: "lanzamiento", cambio: "Se presentó en el Salón de Shanghái como primer modelo construido sobre la arquitectura CMA Evo, estrenando además el sistema Flyme Auto; la producción arrancó en agosto y las entregas chinas, en septiembre.", foto: null }, { anio: 2025, tipo: "restyling", cambio: "Su desembarco europeo se anunció en febrero de 2025 y las ventas comenzaron ese verano desde 52.995 euros, en acabados Core y More, como primer enchufable del mercado europeo con 200 km eléctricos WLTP.", foto: null }, { anio: 2025, tipo: "restyling", cambio: "En septiembre de 2025 Euro NCAP le concedió cinco estrellas, con un 90 % en ocupante adulto y un 87 % en infantil, la puntuación global más alta entre los híbridos enchufables probados ese año.", foto: null }] },
  "mini-aceman-se-2024-precio-ficha-tecnica": { lanzamiento: 2024, hitos: [{ anio: 2022, tipo: "lanzamiento", cambio: "MINI desveló el Concept Aceman en julio de 2022 como primer crossover eléctrico de su nueva familia, con diseño Charismatic Simplicity, sin cuero ni cromo, anticipando un modelo situado entre Cooper y Countryman.", foto: null }, { anio: 2024, tipo: "lanzamiento", cambio: "El Aceman de producción debutó mundialmente en Auto China de Pekín en abril de 2024, ya exclusivamente eléctrico, con cinco plazas, cinco puertas y versiones E y SE dentro de la nueva familia MINI.", foto: null }] },
